CREATE TABLE liquidity_overview AS
SELECT md."EXCH_SPOT", md."TimeTrack", ((md.orderbook_metrics->>'bid_size')::real + (md.orderbook_metrics->>'ask_size')::real) * (md.orderbook_metrics->>'mid_price')::real / s."VOLday" AS liquidity_ratio
FROM marketdata md JOIN marketstats s ON md."EXCH_SPOT" = s.md_link;

